import {commerceConfig} from './commerce-config.mjs';
import {stageLabels} from './commerce-model.mjs';
const allowedReturn=p=>['#account','#checkout','#admin','#collection'].includes(p)?p:'#account';
export function createAccount({openModal,esc,icon,getState,onChange,toast}){
 const connected=commerceConfig.mode==='api',base=commerceConfig.apiBase.replace(/\/$/,'');let config={available:false,ownerRestricted:false},user=null,demoUser=null,demoOwner=false,returnTo='#account',email='',busy=false;
 async function api(path,{method='GET',body}={}){const r=await fetch(base+path,{method,credentials:'same-origin',headers:body?{'Content-Type':'application/json'}:{},...(body?{body:JSON.stringify(body)}:{})});let data;try{data=await r.json()}catch{throw Error('Account service is unavailable. Please try again later.')}if(!r.ok)throw Error(data.error||'Sign-in could not be completed.');return data;}
 function renderButton(){const el=document.querySelector('#account-link');if(!el)return;const active=user||demoUser;el.setAttribute('aria-label',active?'My account':'Sign in or view account');el.title=active?'My account':'Sign in';el.classList.toggle('account-active',!!active);}
 async function initialize(){if(connected)try{config=await api('/api/auth/config');if(config.available)user=(await api('/api/auth/session')).user}catch{config={available:false,ownerRestricted:true}}renderButton();}
 function shell(content){return `<div class="account-shell"><aside class="account-aside"><p class="eyebrow">THE PERSONAL EDIT</p><div><span class="account-aside-number">01 / YOUR SIGNATURE</span><h3>Good taste.<br><em>Remembered.</em></h3><p>A place to return to your orders.<br>A little less searching next time.</p></div><span class="account-aside-foot">DRIP & DUSK / THE FRAGRANCE EDIT</span></aside><section class="account-content">${content}</section></div>`;}
 function guestLink(){return `<a class="account-guest" href="${returnTo==='#checkout'?'#checkout':'#collection'}">${returnTo==='#checkout'?'Continue as guest':'Keep exploring as a guest'} ↗</a>`;}
 function signIn(error=''){
  const ready=config.available,emailReady=ready&&config.methods?.email!==false,googleReady=ready&&config.methods?.google!==false;
  openModal('Your personal edit.',shell(`<p class="eyebrow">${returnTo==='#admin'?'OWNER SIGN-IN':'WELCOME TO DRIP & DUSK'}</p><h3>A scent of<br>something familiar.</h3><p class="account-intro">${returnTo==='#admin'?'Sign in with the account approved to manage this store. Customer accounts cannot open owner tools.':'Sign in to return to your orders. Or keep browsing and check out as a guest.'}</p>${!ready?'<div class="account-preview-note"><b>Account preview</b><span>Google and email sign-in are not connected yet. Use the demo below; no real account is created.</span></div>':''}<button class="btn outline full google-button" data-action="auth-google" ${googleReady?'':'disabled'}><span class="google-g" aria-hidden="true">G</span> Continue with Google</button>${ready&&!googleReady?'<p class="fineprint">Google sign-in is being set up.'+(emailReady?' Use email below.':'')+'</p>':''}<div class="account-divider"><span>or use your email</span></div>${ready&&!emailReady?'<p class="fineprint">Email sign-in is being set up.'+(googleReady?' Continue with Google above.':' You can continue as a guest.')+'</p>':''}<form id="account-email-form"><label for="account-email">Email address</label><input id="account-email" name="email" type="email" placeholder="you@example.com" autocomplete="email" maxlength="254" value="${esc(email)}" required ${emailReady?'':'disabled'}><p class="fineprint">We’ll email a sign-in code. No password to remember.</p><p id="account-error" class="form-error" role="alert">${esc(error)}</p><button class="btn full" type="submit" ${emailReady?'':'disabled'}>Email me a sign-in code ↗</button></form>${!connected?(returnTo==='#admin'?'<a class="account-demo-btn" href="#admin">Back to owner access ↗</a>':'<button class="account-demo-btn" data-action="auth-demo-customer">Explore account demo ↗</button>'):''}${guestLink()}<p class="account-owner-link">Here to manage the collection? <a href="#admin">Owner access ↗</a></p>`),'account','DRIP & DUSK / ACCOUNT');
  document.querySelector('#account-email-form').addEventListener('submit',async e=>{e.preventDefault();if(!emailReady||busy)return;busy=true;const button=e.currentTarget.querySelector('button');button.disabled=true;email=String(new FormData(e.currentTarget).get('email')||'').trim();try{await api('/api/auth/email/start',{method:'POST',body:{email,returnTo}});if(location.hash.startsWith('#account'))codeForm()}catch(e){showError(e.message)}finally{busy=false;button.disabled=false}});
 }
 function showError(message){const el=document.querySelector('#account-error');if(el)el.textContent=message;else toast(message);}
 function codeForm(error=''){
  openModal('Check your inbox.',shell(`<p class="eyebrow">ONE MORE SMALL STEP</p><h3>Make yourself<br>at home.</h3><p class="account-intro">If email delivery is enabled for <b>${esc(email)}</b>, your sign-in code is on its way. Enter it below in this browser.</p><form id="account-code-form"><label for="account-code">Email sign-in code</label><input id="account-code" name="code" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6,10}" minlength="6" maxlength="10" placeholder="Enter your code" required><p id="account-error" class="form-error" role="alert">${esc(error)}</p><button class="btn full" type="submit">Verify & continue ↗</button></form><button class="text-link account-change-email" data-action="auth-change-email">Change email or request a new code</button>${guestLink()}<p class="fineprint">Codes expire. If yours no longer works, request another.</p>`),'account','DRIP & DUSK / EMAIL SIGN-IN');
  document.querySelector('#account-code-form').addEventListener('submit',async e=>{e.preventDefault();if(busy)return;busy=true;const button=e.currentTarget.querySelector('button');button.disabled=true;try{const result=await api('/api/auth/email/verify',{method:'POST',body:{code:new FormData(e.currentTarget).get('code')}});user=result.user;renderButton();onChange();const target=allowedReturn(result.returnTo);if(target==='#account')await accountView();else location.hash=target;}catch(e){showError(e.message)}finally{busy=false;button.disabled=false}});
 }
 async function accountView(){
  const current=user||demoUser;if(!current)return signIn();let orders=[],error='';
  if(connected)try{orders=(await api('/api/account/orders')).orders}catch(e){error=e.message}else orders=(getState().demoOrders||[]).map(o=>({...o,trackingPath:'#track/'+o.id+'/'+o.token}));
  if(!location.hash.startsWith('#account'))return;
  const orderRows=orders.map(o=>`<a class="account-order" href="${/^#track\/[A-Za-z0-9-]+\/[A-Za-z0-9_-]+$/.test(o.trackingPath)?esc(o.trackingPath):'#account'}"><span><small>${esc(o.ref)}</small><b>${esc(stageLabels[o.status]||o.status)}</b><em>${o.lines.map(l=>esc(l.name)+' × '+l.qty).join(' · ')}</em></span><span>Track ↗</span></a>`).join('');
  openModal('A space for your signatures.',`<div class="account-dashboard">${demoUser?'<div class="account-preview-note"><b>Example account</b><span>No real sign-in. The orders below are demo orders saved on this device, not a verified customer history.</span></div>':''}<div class="account-profile"><span class="account-avatar" aria-hidden="true">${esc(current.name.slice(0,2).toUpperCase())}</span><div><p class="eyebrow">${user?.role==='owner'?'OWNER ACCOUNT':'YOUR PERSONAL EDIT'}</p><h3>${esc(current.name)}</h3><p>${esc(current.email)}</p></div><button class="text-link" data-action="auth-signout">${demoUser?'Exit preview':'Sign out'}</button></div><div class="account-orders-heading"><h3>${demoUser?'Demo orders on this device':'Your orders'}</h3><a class="text-link" href="#collection">Find your next signature ↗</a></div>${error?`<p class="form-error" role="alert">${esc(error)}</p>`:orderRows||'<div class="account-empty"><span>01 / A FRESH START</span><h4>Your story is just beginning.</h4><p>Orders placed while signed in will appear here. Guest orders remain accessible through their private tracking links.</p><a class="btn outline" href="#collection">Explore the collection ↗</a></div>'}<div class="account-dashboard-foot"><button class="text-link" data-action="auth-saved">View favourites on this device ${icon('heart')}</button>${user?.role==='owner'?'<a class="text-link" href="#admin">Open owner studio ↗</a>':''}</div><p class="fineprint">Favourites currently stay on this device. Signing in does not claim older guest orders or subscribe you to marketing.</p></div>`,'account','DRIP & DUSK / MY ACCOUNT');
 }
 async function open(target='#account',error=''){returnTo=allowedReturn(target);if(connected&&config.available)try{user=(await api('/api/auth/session')).user;renderButton()}catch{user=null;error='Your session could not be verified. Please sign in again.'}if(!location.hash.startsWith('#account'))return;if(returnTo==='#admin'){if(user?.role==='owner'){location.hash='#admin';return;}if(user||demoUser)return signIn('Use the account approved for owner access. A customer account cannot manage the store.');}if(user||demoUser)return accountView();signIn(error);}
 function ownerGate(container){
  if(!connected&&demoOwner)return false;if(connected&&!config.ownerRestricted)return false;if(connected&&user?.role==='owner')return false;
  container.innerHTML=`<a class="text-link" href="#collection">← Back to storefront</a><section class="owner-auth-gate"><span class="owner-lock">${icon('lock')}</span><p class="eyebrow">DRIP & DUSK / OWNER ACCESS</p><h1>A collection<br>in trusted hands.</h1><p>${user?'This account does not have owner access. Only an account approved on the server can manage orders.':'Owner access is separate from customer accounts. Sign in with the account approved to manage this store.'}</p><a class="btn" href="#account/admin">${user?'Use approved owner account':'Owner sign-in'} ↗</a>${!connected?'<div class="account-preview-note"><b>Public demo</b><span>Real owner authentication needs the connected server and Supabase project. The local demo below edits sample data only and provides no production security.</span></div><button class="text-link" data-action="auth-demo-owner">Open local demo studio ↗</button>':''}<p class="fineprint">Customers can browse and check out as guests.</p></section>`;return true;
 }
 async function handle(action){
  if(action==='auth-google'){if(!config.available||config.methods?.google===false||busy)return;busy=true;try{const result=await api('/api/auth/google/start',{method:'POST',body:{returnTo}}),url=new URL(result.url);if(url.protocol!=='https:')throw Error('Invalid sign-in destination.');location.assign(url.href)}catch(e){showError(e.message)}finally{busy=false}}
  if(action==='auth-change-email')signIn();
  if(action==='auth-demo-customer'&&!connected){demoUser={name:'Fragrance Explorer',email:'customer@example.test',role:'customer'};renderButton();accountView();}
  if(action==='auth-demo-owner'&&!connected){demoOwner=true;onChange();}
  if(action==='auth-lock-demo-owner'){demoOwner=false;onChange();}
  if(action==='auth-signout'){if(connected)await api('/api/auth/logout',{method:'POST',body:{}});user=null;demoUser=null;demoOwner=false;email='';returnTo='#account';renderButton();onChange();if(location.hash!=='#account')location.hash='#account';else signIn();}
  if(action==='auth-saved'){location.hash='#collection';document.querySelector('[data-action=show-favourites]').click();}
 }
 return {initialize,open,handle,ownerGate,get user(){return user},get ownerRequired(){return config.ownerRestricted}};
}
